 324	static Ncv32u getPaddedDimension(Ncv32u dim, Ncv32u elemTypeSize, Ncv32u allocatorAlignment)
 325	{
 326	    Ncv32u alignMask = allocatorAlignment-1;
 327	    Ncv32u inverseAlignMask = ~alignMask;
 328	    Ncv32u dimBytes = dim * elemTypeSize;
 329	    Ncv32u pitch = (dimBytes + alignMask) & inverseAlignMask;
 330	    Ncv32u PaddedDim = pitch / elemTypeSize;
 331	    return PaddedDim;
