 869	{
 870	    if (tbCacheTexture)
 871	    {
 872	        uint2 tmp = tex1Dfetch(tex64u, x);
 873	        Ncv64u res = (Ncv64u)tmp.y;
 874	        res <<= 32;
 875	        res |= tmp.x;
