 885	template <NcvBool tbCacheTexture>
 886	__global__ void rectStdDev_32f_C1R(Ncv32u *d_sum, Ncv32u sumStep,
 887	                                   Ncv64u *d_sqsum, Ncv32u sqsumStep,
 888	                                   Ncv32f *d_norm, Ncv32u normStep,
 889	                                   NcvSize32u roi, NcvRect32u rect, Ncv32f invRectArea)
 890	{
 891	    Ncv32u x_offs = blockIdx.x * NUM_RECTSTDDEV_THREADS + threadIdx.x;
 892	    if (x_offs >= roi.width)
 893	    {
 894	        return;
 895	    }
 896	
 897	    Ncv32u sum_offset = blockIdx.y * sumStep + x_offs;
 898	    Ncv32u sqsum_offset = blockIdx.y * sqsumStep + x_offs;
 899	
 900	    //OPT: try swapping order (could change cache hit/miss ratio)
 901	    Ncv32u sum_tl = getElemSum<tbCacheTexture>(sum_offset + rect.y * sumStep + rect.x, d_sum);
 902	    Ncv32u sum_bl = getElemSum<tbCacheTexture>(sum_offset + (rect.y + rect.height) * sumStep + rect.x, d_sum);
 903	    Ncv32u sum_tr = getElemSum<tbCacheTexture>(sum_offset + rect.y * sumStep + rect.x + rect.width, d_sum);
 904	    Ncv32u sum_br = getElemSum<tbCacheTexture>(sum_offset + (rect.y + rect.height) * sumStep + rect.x + rect.width, d_sum);
 905	    Ncv32u sum_val = sum_br + sum_tl - sum_tr - sum_bl;
 906	
 907	    Ncv64u sqsum_tl, sqsum_bl, sqsum_tr, sqsum_br;
 908	    sqsum_tl = getElemSqSum<tbCacheTexture>(sqsum_offset + rect.y * sqsumStep + rect.x, d_sqsum);
 909	    sqsum_bl = getElemSqSum<tbCacheTexture>(sqsum_offset + (rect.y + rect.height) * sqsumStep + rect.x, d_sqsum);
 910	    sqsum_tr = getElemSqSum<tbCacheTexture>(sqsum_offset + rect.y * sqsumStep + rect.x + rect.width, d_sqsum);
 911	    sqsum_br = getElemSqSum<tbCacheTexture>(sqsum_offset + (rect.y + rect.height) * sqsumStep + rect.x + rect.width, d_sqsum);
 912	    Ncv64u sqsum_val = sqsum_br + sqsum_tl - sqsum_tr - sqsum_bl;
 913	
 914	    Ncv32f mean = sum_val * invRectArea;
 915	
 916	    //////////////////////////////////////////////////////////////////////////
 917	    // sqsum_val_res = sqsum_val / rectArea
 918	    //////////////////////////////////////////////////////////////////////////
 919	
 920	    Ncv32f sqsum_val_1 = __ull2float_rz(sqsum_val);
 921	    Ncv64u sqsum_val_2 = __float2ull_rz(sqsum_val_1);
 922	    Ncv64u sqsum_val_3 = sqsum_val - sqsum_val_2;
 923	    Ncv32f sqsum_val_4 = __ull2float_rn(sqsum_val_3);
 924	    sqsum_val_1 *= invRectArea;
 925	    sqsum_val_4 *= invRectArea;
 926	    Ncv32f sqsum_val_res = sqsum_val_1 + sqsum_val_4;
 927	
 928	    //////////////////////////////////////////////////////////////////////////
 929	    // variance = sqsum_val_res - mean * mean
 930	    //////////////////////////////////////////////////////////////////////////
 931	
 932	#if defined DISABLE_MAD_SELECTIVELY
 933	    Ncv32f variance = sqsum_val_2 - __fmul_rn(mean, mean);
 934	#else
 935	    Ncv32f variance = sqsum_val_res - mean * mean;
 936	#endif
 937	
 938	    //////////////////////////////////////////////////////////////////////////
 939	    // stddev = sqrtf(variance)
 940	    //////////////////////////////////////////////////////////////////////////
 941	
 942	    //Ncv32f stddev = sqrtf(variance);
 943	    Ncv32f stddev = __fsqrt_rn(variance);
 944	
 945	    d_norm[blockIdx.y * normStep + x_offs] = stddev;
 946	}
