s=s.replace('''                                  int w, int h, int s, 
                                  float theta, float *out)''','''                                  int w, int h, int s,
                                  float theta, float *out,
                                  cudaTextureObject_t src0Tex, cudaTextureObject_t src1Tex)''')
s=s.replace('tex2D(tex_src0,','tex2D<float>(src0Tex,').replace('tex2D(tex_src1,','tex2D<float>(src1Tex,')
# replace setup from old properties through bind with object descriptors
st=s.index('    tex_src1.addressMode[0]',s.index('NCVStatus BlendFrames'))
en=s.index('    dim3 threads',st)
rep='''    cudaResourceDesc resource{};
    resource.resType = cudaResourceTypePitch2D;
    resource.res.pitch2D.desc = cudaCreateChannelDesc<float>();
    resource.res.pitch2D.width = width;
    resource.res.pitch2D.height = height;
    resource.res.pitch2D.pitchInBytes = stride * sizeof(float);

    cudaTextureDesc textureDesc{};
    textureDesc.addressMode[0] = cudaAddressModeClamp;
    textureDesc.addressMode[1] = cudaAddressModeClamp;
    textureDesc.filterMode = cudaFilterModeLinear;
    textureDesc.readMode = cudaReadModeElementType;
    textureDesc.normalizedCoords = 0;

    cudaTextureObject_t src0Tex = 0, src1Tex = 0;
    resource.res.pitch2D.devPtr = const_cast<Ncv32f*>(src0);
    ncvAssertCUDAReturn(cudaCreateTextureObject(&src0Tex, &resource, &textureDesc, nullptr), NPPST_TEXTURE_BIND_ERROR);
    resource.res.pitch2D.devPtr = const_cast<Ncv32f*>(src1);
