289	              float F = fetch (buffer, x, y, z, W);
290	
291	              if (W != 0.0f && F != 1.f && F < 0.98 && F != 0.0f && F > -1.0f)
292	              {
293	                float4 p;
294	                p.x = x;
295	                p.y = y;
296	                p.z = z;
297	                p.w = F;
298	                points[local_count++] = p;
299	              }
300	            }/* if (x < VOLUME_X && y < VOLUME_Y) */
301	
302	            // local_count counts the number of zero crossing for the current thread. Now we need to merge this knowledge with the other threads
303	            // not we fulfilled points array at current iteration
304	            int total_warp = __popc (__ballot_sync (__activemask (), local_count > 0))
305	                           + __popc (__ballot_sync (__activemask (), local_count > 1))
306	                           + __popc (__ballot_sync (__activemask (), local_count > 2));
307	
308	            if (total_warp > 0)  ///more than 0 zero-crossings
309	            {
