329	              // Perform compaction (dump all current crossings)
330	              for (int l = 0; l < local_count; ++l)
331	              {
332	                storage_X[storage_index + offset + l] = points[l].x;// x coordinates of the points we found in STORAGE_X
333	                storage_Y[storage_index + offset + l] = points[l].y;// y coordinates of the points we found in STORAGE_Y
334	                storage_Z[storage_index + offset + l] = points[l].z;// z coordinates of the points we found in STORAGE_Z
335	                storage_I[storage_index + offset + l] = points[l].w;// Intensity values of the points we found in STORAGE_I
336	              }
337	
338	              // Retrieve Zero-crossings as 3D points
339	              int offset_storage = old_global_count + lane;
340	              for (int idx = lane; idx < total_warp; idx += Warp::STRIDE, offset_storage += Warp::STRIDE)
341	              {
342	                if (offset_storage >= output_xyz.size) break;
343	                float x = storage_X[storage_index + idx];
344	                float y = storage_Y[storage_index + idx];
345	                float z = storage_Z[storage_index + idx];
346	                float i = storage_I[storage_index + idx];
347	                store_point_intensity (x, y, z, i, output_xyz.data, output_intensity.data, offset_storage);
348	              }
349	
350	              // Sanity check to make sure our output_xyz buffer is not full already
351	              bool full = (old_global_count + total_warp) >= output_xyz.size;
352	
353	              if (full)
354	                break;
355	            }
356	
357	            } /* for(int z = 0; z < VOLUME_Z - 1; ++z) */
358	
359	          ///////////////////////////
360	          // Prepare for future scans
361	          if (ftid == 0)
362	          {
363	            unsigned int total_blocks = gridDim.x * gridDim.y * gridDim.z;
364	            unsigned int value = atomicInc (&blocks_done, total_blocks);
365	
366	            // Last block
367	            if (value == total_blocks - 1)
368	            {
369	              output_xyz_count = min ((int)output_xyz.size, global_count);
370	              blocks_done = 0;
371	              global_count = 0;
372	            }
373	          }
374	        } /* operator() */
